            raise ClockUnavailable("anchor_write_failed") from None
        finally:
            if temporary.exists():
                temporary.unlink()

    def save(self):
        with self.lock:
            self._wait_for_compactions()
            try:
                self._save_locked()
            except ClockUnavailable as exc:
                self.status = "rejected"; self.last_error = str(exc)
                raise

